export function calibrationMetrics(pairs=[]){const valid=pairs.filter(x=>Number.isFinite(x.error));if(!valid.length)return{count:0,mae:null,bias:null,rmse:null};const n=valid.length,abs=valid.reduce((s,x)=>s+Math.abs(x.error),0),sum=valid.reduce((s,x)=>s+x.error,0),sq=valid.reduce((s,x)=>s+x.error*x.error,0);return{count:n,mae:abs/n,bias:sum/n,rmse:Math.sqrt(sq/n)};}
export function promotionGate(model,{minCount=30,maxMae=Infinity,maxAbsBias=Infinity}={}){const m=model.metrics||{};return Number(m.count)>=minCount&&Number(m.mae)<=maxMae&&Math.abs(Number(m.bias))<=maxAbsBias&&Array.isArray(model.evidence)&&model.evidence.length>0;}
